local B = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local M = {}
for i = 1, 64 do
    M[B:sub(i, i)] = i - 1
end

local function unb64(s)
    local out, buf, bits, n = {}, 0, 0, 0
    for i = 1, #s do
        local v = M[s:sub(i, i)]
        if v then
            buf = buf * 64 + v
            bits = bits + 6
            while bits >= 8 do
                bits = bits - 8
                local p = 2 ^ bits
                n = n + 1
                out[n] = string.char(math.floor(buf / p) % 256)
                buf = buf % p
            end
        end
    end
    return table.concat(out)
end

local raw = unb64(table.concat(P))
local total, kb = #raw, #K
local bytes = {}
for i = 1, total do
    bytes[i] = string.char(bit32.bxor(string.byte(raw, i), K[((i - 1) % kb) + 1]))
end

local src = table.concat(bytes)

local fn, err = loadstring(src)
if not fn then
    return warn("[OBJ Wireframe] 解包后编译失败：" .. tostring(err))
end

local ok, runErr = pcall(fn)
if not ok then
    warn("[OBJ Wireframe] 运行时报错：" .. tostring(runErr))
end
